import{z as n,x as p,o as t,c as A,q as E,j as r,D as e,d as i,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"EUV 胶的吸收与厚度","description":"","frontmatter":{"title":"EUV 胶的吸收与厚度","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-resist-absorption.md","filePath":"litho/euv-resist-absorption.md","lastUpdated":1791413859000}'),B={name:"litho/euv-resist-absorption.md"};function h(d,a,u,m,_,T){const l=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=E('<h1 id="euv-胶的吸收与厚度" tabindex="-1">EUV 胶的吸收与厚度 <a class="header-anchor" href="#euv-胶的吸收与厚度" aria-label="Permalink to &quot;EUV 胶的吸收与厚度&quot;">​</a></h1><div class="epigraph"><p>Beer 定律在 13.5 nm 很陡：膜必须够薄才侧壁直，又必须够吸收才有光子事件。厚度从此不是刻蚀余量的自由变量。</p><footer>—— 对照 Levinson、Mack 对吸收与胶厚；Naulleau 对 EUV 吸收与模糊</footer></div><p><a href="/litho/pellicle-free-risk">上一课</a>从掩模防护回到硅片。缺口是记录介质：<a href="/litho/euv-resist">EUV 胶</a> 已把 CAR 与金属氧化物的 RLS 工作点分开；本课专攻吸收系数与厚度如何互锁。底层如何向胶里灌二次电子，留给<a href="/litho/underlayer-secondary-electron">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无膜课把额外光子送给硅片。胶能不能用上，取决于膜内吸收。13.5 nm 下有机 CAR 的吸收长度往往只有几十纳米量级，膜厚与吸收长度同量级：太厚，顶底剂量差大，侧壁斜、清底难；太薄，体积 \\(V\\) 里平均光子数 \\(\\bar N=\\sigma D V\\) 不够，泊松先于平均 CD 爆。金属氧化物靠高 \\(\\sigma\\)（金属）允许更薄仍收够事件，这是化学课的吸收轴，本课把它写成厚度预算。</p><p><span class="marginnote">吸收长度（\\(1/\\alpha\\)）翻译一下：光强衰减到约 37%（\\(1/e\\)）所走过的厚度。可见光下胶几乎透明，吸收长度以微米计；13.5 nm 下有机胶只有几十纳米——同一张膜，在 EUV 里相当于深色墨镜，这就是厚度变成硬预算的原因。</span></p><p>缺口不是再选一次 PAG 或锡氧笼，而是：给定 \\(\\alpha\\)（或光学密度），\\(t\\) 还能涂多少。<a href="/litho/high-na-resist-budget">High-NA 胶厚</a> 已从焦深和倒塌切入；本课从光子吸收切入，两张表必须交。</p> \\[I(z)=I_0 e^{-\\alpha z},\\qquad \\bar N \\propto (1-e^{-\\alpha t})\\,D. \\]<p><span class="marginnote">\\(\\alpha\\) 随元素和密度变。加剂量加的是 \\(D\\)，加金属加的是 \\(\\alpha\\)。只加 \\(D\\) 会顶光源和出气；只减 \\(t\\) 会顶 \\(\\bar N\\) 和刻蚀。</span></p>',9)),(t(),r(s,null,{default:e(()=>[o(l,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%86%9C%E5%8E%9A%20t%20%E6%80%8E%E4%B9%88%E9%80%89%3F%22%5D%20--%3E%20TH%5B%22t%20%E5%A4%AA%E5%8E%9A%22%5D%0A%20%20Q%20--%3E%20TL%5B%22t%20%E5%A4%AA%E8%96%84%22%5D%0A%20%20TH%20--%3E%20TH1%5B%22%CE%B1t%20%E5%A4%A7%20%E9%A1%B6%E5%BA%95%E5%89%82%E9%87%8F%E5%B7%AE%E5%A4%A7%22%5D%0A%20%20TH1%20--%3E%20TH2%5B%22%E4%BE%A7%E5%A3%81%E6%96%9C%20%E6%B8%85%E5%BA%95%E9%9A%BE%22%5D%0A%20%20TL%20--%3E%20TL1%5B%22%CE%B1t%20%E5%B0%8F%20%E5%90%B8%E6%94%B6%E5%85%89%E5%AD%90%E5%B0%91%22%5D%0A%20%20TL1%20--%3E%20TL2%5B%22%E6%AF%8F%E7%82%B9%E4%BA%8B%E4%BB%B6%E6%95%B0%E4%B8%8D%E5%A4%9F%20%E5%AD%94%E9%9A%8F%E6%9C%BA%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20TL%20--%3E%20TL3%5B%22%E5%88%BB%E8%9A%80%E4%BD%99%E9%87%8F%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20TH2%20--%3E%20M%5B%22%E5%B7%A5%E4%BD%9C%E7%82%B9%E5%8D%A1%E5%9C%A8%E4%B8%AD%E9%97%B4%22%5D%0A%20%20TL2%20--%3E%20M%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p><span class="marginnote">数字实例：吸收长度 30 nm 时涂 60 nm 厚，膜底光强只剩 \\(e^{-2}\\approx 13\\%\\)——底部剂量不到顶部两成，侧壁必然上直下斜。想让底部也有八成光，膜就得压到 7 nm 上下，光子统计又转不动了。出路不是调厚度，而是加金属把 \\(\\alpha\\) 提上去。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测：EUV 或等效的膜吸收、对比曲线随厚变化、侧壁角。选：CAR 往往停在约二三十纳米量级（层别而异）；High-NA 和倒塌把目标推向更薄，必须靠 \\(\\alpha\\) 或底层电子补 \\(\\bar N\\)。转印：薄胶把硬掩模功能下放到栈，下一课之后的图形转移课展开。</p><p>与随机：同样 \\(D\\)，吸收分数 \\((1-e^{-\\alpha t})\\) 决定事件数。透明胶「侧壁好看」但孔缺失；不透明胶「光子够」但顶底差。工作点在中间。</p><h3 id="沿-z-的剂量差就是剖面" tabindex="-1">沿 z 的剂量差就是剖面 <a class="header-anchor" href="#沿-z-的剂量差就是剖面" aria-label="Permalink to &quot;沿 z 的剂量差就是剖面&quot;">​</a></h3><p>\\(e^{-\\alpha t}\\) 是膜底相对膜顶的剩余光。\\(\\alpha t\\) 太大，显影阈值只能切在某一深度，侧壁必斜或顶圆。\\(\\alpha t\\) 太小，整膜事件稀疏。金属氧化物提高 \\(\\alpha\\)，允许更小 \\(t\\) 仍维持 \\(\\alpha t\\) 在可剖面的窗——化学课的吸收轴在这里变成剖面轴。底层电子再从底部灌入，下一课会把这条 Beer 曲线弯曲。</p>',6)),(t(),r(s,null,{default:e(()=>[o(l,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%90%B8%E6%94%B6%E7%B3%BB%E6%95%B0%20%CE%B1%22%5D%20--%3E%20T%5B%22%E8%86%9C%E5%8E%9A%20t%22%5D%0A%20%20T%20--%3E%20SW%5B%22%E9%A1%B6%E5%BA%95%E5%89%82%E9%87%8F%E5%B7%AE%20%2F%20%E4%BE%A7%E5%A3%81%22%5D%0A%20%20T%20--%3E%20N%5B%22%E5%85%89%E5%AD%90%E4%BA%8B%E4%BB%B6%E6%95%B0%22%5D%0A%20%20N%20--%3E%20STO%5B%22%E9%9A%8F%E6%9C%BA%E5%A4%B1%E6%95%88%22%5D%0A%20%20SW%20--%3E%20PROF%5B%22%E5%89%96%E9%9D%A2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/litho/euv-absorption-blur">吸收与模糊</a> 已指出：吸收位置是二次电子的出生点。\\(\\alpha\\) 高则事件密、但沿 z 衰减快；电子再把潜像沿几纳米核抹开。厚度选择等于在「纵向均匀」和「统计足够」之间切。Mack 的显影模型仍适用：曝光能量密度随 z 变，溶解速率随 z 变，剖面是积分结果。</p><p><span class="marginnote">常见误区：以为「胶越厚越耐刻蚀、越保险」。这条 ArF 时代的经验到 EUV 失效——吸收长度只有几十纳米，厚胶底部根本晒不透，剖面先崩。耐刻蚀任务转给了底层硬掩模或金属氧化物胶自身，厚度的自由度被吸收物理收走了。</span></p><p><span class="marginnote">不要把 ArF 的「厚胶 = 耐刻」搬过来。EUV 吸收长度不允许那张保险；耐刻改由底层或金属胶承担。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把底层二次电子产额写完，下一课才把 underlayer 当电子源。不重写 CAR vs 金属氧化物化学。出处：Levinson；Mack；Naulleau 吸收/模糊；High-NA 胶厚课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>厚度由 \\(\\alpha\\)、侧壁、光子统计和倒塌共同决定，不是刻蚀单向加厚。</li><li>吸收分数 \\((1-e^{-\\alpha t})\\) 才是随机项的分子。</li><li>下一课：底层向这张薄膜灌入的二次电子。</li><li>出处：Levinson、Mack、Naulleau。</li></ul>',8))])}const f=n(B,[["render",h]]);export{c as __pageData,f as default};
